const APP_KEY='careerbrand-v1'; // Preserve existing browser profiles from v1.0
const blank=()=>({lang:'kk',page:'overview',profile:{name:'',role:'',city:'',email:'',summary:'',skills:'',education:'',experience:'',achievements:'',goal:'',strengths:'',audience:'',value:''},projects:[],messages:[],market:null,agent:null,marketParams:{query:'Data Analyst',area:'160'},courseMeta:{author:'',university:'Narxoz University',major:'',year:'2026',subject:'АКТ'},demoActive:false});
function load(){try{const v=JSON.parse(localStorage.getItem(APP_KEY)||'null');if(v && typeof v==='object' && v.profile && I[v.lang])return {...blank(),...v,profile:{...blank().profile,...v.profile},courseMeta:{...blank().courseMeta,...v.courseMeta},agent:null};}catch{}return blank()}
let S=load(),apiReady=false,chatBusy=false,marketBusy=false,agentBusy=false;
const root=document.getElementById('app');
const tr=k=>(I[S.lang][k]??I.kk[k]??k);
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmt=(k,values={})=>tr(k).replace(/\{([a-zA-Z]+)\}/g,(_,key)=>String(values[key]??''));
const nl=x=>esc(x).replace(/\n/g,'<br>');
const save=()=>{try{localStorage.setItem(APP_KEY,JSON.stringify({...S,messages:S.messages.slice(-10),market:null,agent:null}));}catch{}};
const skills=()=>S.profile.skills.split(/[,;\n]/).map(v=>v.trim()).filter(Boolean);
const completed=()=>{const p=S.profile;return Math.round([p.name,p.role,p.city,p.email,p.summary.length>=80?p.summary:'',p.education,p.experience,skills().length>=3?'yes':'',p.achievements].filter(Boolean).length/9*100)};
const pitem=(x)=>'<span class="pill">'+esc(x)+'</span>';
const icon={overview:'◈',brand:'✦',resume:'▤',portfolio:'▦',video:'▷',market:'▥',assistant:'✧'};
function template(k){return `<div class="section-header"><div class="eyebrow">${tr(k+'Eyebrow')===''+k+'Eyebrow'?'':tr(k+'Eyebrow')}</div><h1>${tr(k+'Title')}</h1><p class="subtle">${tr(k+'Sub')}</p></div>`}
function pageHeader(k){return `<div class="section-header"><div class="eyebrow">${tr(k+'Eyebrow')}</div><h1>${tr(k+'Title')}</h1><p class="subtle">${tr(k+'Sub')}</p></div>`}
function field(key,label,placeholder='',multi=false){let value=esc(S.profile[key]);return `<div class="field"><label for="field-${key}">${tr(label)}</label>${multi?`<textarea rows="3" id="field-${key}" data-field="${key}" placeholder="${esc(tr(placeholder))}">${value}</textarea>`:`<input id="field-${key}" data-field="${key}" value="${value}" placeholder="${esc(tr(placeholder))}">`}</div>`}
function shell(){
 const navs=['overview','brand','resume','portfolio','video','market','assistant'];
 root.innerHTML=`<div class="app-shell"><aside class="side"><div class="brand"><div class="brand-icon">✦</div><div><div class="brand-name">CareerBrand <b>AI</b></div><div class="brand-sub">Build your own future.</div></div></div><div class="nav-caption">${tr('navTitle')}</div><nav class="nav" aria-label="Navigation">${navs.map(n=>`<button type="button" class="nav-link ${S.page===n?'active':''}" data-page="${n}"><span class="nav-ico">${icon[n]}</span>${tr(n)}</button>`).join('')}</nav><div class="side-info"><strong><span class="online"></span>CareerBrand AI v1.1</strong><p>${tr('menuHelp')}</p></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">CareerBrand AI / <b>${tr(S.page)}</b></div><div class="top-actions"><span class="mode">${tr('demo')}</span><select id="language" class="language-picker" aria-label="Language"><option value="kk" ${S.lang==='kk'?'selected':''}>🇰🇿 Қазақша</option><option value="ru" ${S.lang==='ru'?'selected':''}>🇷🇺 Русский</option><option value="en" ${S.lang==='en'?'selected':''}>🇬🇧 English</option></select><div class="user-bubble" aria-hidden="true">${esc((S.profile.name.trim()[0]||'A').toUpperCase())}</div></div></header><main class="container" id="content"></main></div></div>`;
 renderPage();
}
const foot=()=>`<footer class="footer"><strong>${tr('footer')}</strong><br>${tr('metaAuthor')}: ${esc(S.courseMeta.author||tr('metaPending'))} · ${tr('metaSubject')}: ${esc(S.courseMeta.subject)}<br>${tr('metaUniversity')}: ${esc(S.courseMeta.university)} · ${tr('metaMajor')}: ${esc(S.courseMeta.major||'—')} · ${tr('metaYear')}: ${esc(S.courseMeta.year)}<br>${tr('storage')}</footer>`;
function metaEditor(){return `<section class="card" style="margin-top:20px"><h2>${tr('metaHeading')}</h2><p class="subtle" style="margin:8px 0 16px">${tr('metaInfo')}</p><div class="fieldrow">${[['author','metaAuthor'],['university','metaUniversity'],['major','metaMajor'],['year','metaYear'],['subject','metaSubject']].map(([key,label])=>`<div class="field"><label for="meta-${key}">${tr(label)}</label><input id="meta-${key}" data-meta="${key}" maxlength="140" value="${esc(S.courseMeta[key])}"></div>`).join('')}</div></section>`} 
function overview(){const cards=[['brand','featureBrand'],['resume','featureResume'],['portfolio','featurePortfolio'],['video','featureVideo'],['market','featureMarket'],['assistant','featureAssistant']];return `<div class="section-header"><div class="eyebrow">${tr('pageIntro')}</div><h1>${tr('homeTitle')}</h1><p class="subtle">${tr('homeSub')}</p></div><section class="hero"><div><div class="eyebrow">${tr('heroEyebrow')}</div><h2>${tr('heroTitle')}</h2><p>${tr('heroSub')}</p><button class="btn white" data-page="resume">${tr('heroButton')} ↗</button></div><div class="hero-symbol"><span>✦</span></div></section><div class="grid" style="margin-top:17px"><div class="card"><div class="kpi"><div class="ico">◉</div><div><div class="hint">${tr('completion')}</div><strong>${completed()}%</strong></div></div><div class="meter"><span style="width:${completed()}%"></span></div></div><div class="card"><div class="kpi"><div class="ico">▦</div><div><div class="hint">${tr('projects')}</div><strong>${S.projects.length}</strong></div></div><p class="hint">${tr('storage')}</p></div></div><div class="section-row"><h2>${tr('stepsTitle')}</h2></div><div class="card"><div class="steps">${[1,2,3].map((i)=>`<div class="step"><span class="step-num">0${i}</span><div><h3>${tr('step'+i)}</h3><p>${tr('step'+i+'sub')}</p></div></div>`).join('')}</div></div><div class="section-row"><h2>${tr('features')}</h2></div><div class="grid three">${cards.map(([k,d])=>`<button class="feature" data-page="${k}"><span class="ico">${icon[k]}</span><span><h3>${tr(k)}</h3><p>${tr(d)}</p></span></button>`).join('')}</div><div class="section-row"><div class="btn-row"><button class="btn outline small" data-action="demo">${tr('sample')}</button><button class="btn warn small" data-action="reset">${tr('reset')}</button></div></div>${S.demoActive?`<div class="notice warning">${tr('demoWarning')}</div>`:''}${metaEditor()}${foot()}`}
function brandStatement(){const p=S.profile;if(!p.role&&!p.goal&&!p.value)return tr('emptyProfile');return fmt('brandDefault',{role:p.role||'…',strengths:p.strengths||'…',audience:p.audience||'…',value:p.value||'…',goal:p.goal||'…'})}
function brand(){return pageHeader('brand')+`<div class="grid"><section class="card"><h2 style="margin-bottom:19px">${tr('brandTitle')}</h2>${field('goal','target','targetPlaceholder',true)}${field('strengths','strengths','strengthsPlaceholder',true)}${field('audience','audience','audiencePlaceholder')}${field('value','value','valuePlaceholder',true)}</section><section class="card"><h2>${tr('position')}</h2><div id="brand-text" class="brand-quote">${esc(brandStatement())}</div><p class="subtle">${tr('brandDisclaimer')}</p><button class="btn soft" data-action="copy-brand" style="margin-top:17px">${tr('copy')}</button><hr class="divider"><h2>${tr('roadmap')}</h2><div class="steps" style="margin-top:11px">${[1,2,3,4].map(n=>`<div class="step"><span class="step-num">${n}</span><div><h3>${tr('week'+n)}</h3><p>${tr('week'+n+'desc')}</p></div></div>`).join('')}</div></section></div>${foot()}`}
function cvPaper(){const p=S.profile;return `<div class="cv-name">${esc(p.name||tr('name'))}</div><div class="cv-job">${esc(p.role||tr('role'))}</div><div class="cv-meta">${esc([p.city,p.email].filter(Boolean).join(' · '))}</div><div class="cv-line"></div><h4>${tr('about')}</h4><p>${nl(p.summary||tr('missing'))}</p><h4>${tr('skillsHead')}</h4><div>${skills().length?skills().map(pitem).join(''):pitem(tr('noSkills'))}</div><h4>${tr('eduHead')}</h4><p>${nl(p.education||tr('missing'))}</p><h4>${tr('expHead')}</h4><p>${nl(p.experience||tr('missing'))}</p>${p.achievements?`<h4>${tr('achHead')}</h4><p>${nl(p.achievements)}</p>`:''}`}
function resume(){return pageHeader('cv')+`${S.demoActive?`<div class="notice warning" style="margin-bottom:16px">${tr('demoWarning')}</div>`:''}<div class="grid" style="align-items:start"><section class="card"><h2 style="margin-bottom:18px">${tr('personal')}</h2><div class="fieldrow">${field('name','name')}${field('role','role','exampleRole')}${field('city','city','exampleCity')}${field('email','email')}</div>${field('summary','summary','exampleAbout',true)}${field('skills','skills','exampleSkills')}${field('education','education','exampleEdu',true)}${field('experience','experience','exampleExp',true)}${field('achievements','achievements','exampleResult',true)}<div class="meter"><span class="completion-bar" style="width:${completed()}%"></span></div><p class="hint" id="cv-completion">${tr('completion')}: ${completed()}%</p></section><section class="card"><div class="cv-preview-title"><h2>${tr('preview')}</h2><button class="btn soft small" data-action="print">↗ ${tr('pdf')}</button></div><div class="cv-paper" id="cv-paper">${cvPaper()}</div><p class="hint" style="margin-top:11px">${tr('printNote')}</p></section></div><div class="notice" style="margin-top:16px">${tr('privacy')}</div>${foot()}`}
function portfolio(){const p=S.profile;const projects=S.projects.map((x,i)=>`<div class="project"><div class="ico">▦</div><h3>${esc(x.name)}</h3><p class="subtle">${nl(x.desc)}</p>${x.link&&/^https?:\/\//i.test(x.link)?`<a href="${esc(x.link)}" rel="noopener noreferrer" target="_blank">${esc(x.link)}</a>`:''}<div><button class="btn warn small" data-action="remove-project" data-id="${i}">${tr('delete')}</button></div></div>`).join('');return pageHeader('portfolio')+`<div class="card"><div class="profile-cover"><div class="profile-avatar">${esc((p.name[0]||'A').toUpperCase())}</div><div><h2>${esc(p.name||tr('name'))}</h2><p class="subtle">${esc([p.role,p.city].filter(Boolean).join(' · '))}</p></div></div><p class="subtle" style="margin-top:17px">${esc(p.summary||tr('missing'))}</p><div style="margin-top:11px">${skills().map(pitem).join('')}</div></div><div class="section-row"><h2>${tr('myProjects')}</h2><span class="state">${S.projects.length}</span></div>${S.projects.length?`<div class="grid">${projects}</div>`:`<div class="empty"><div class="empty-icon">▦</div><h3>${tr('projectEmpty')}</h3></div>`}<section class="card" style="margin-top:17px"><h2 style="margin-bottom:16px">${tr('addProject')}</h2><div class="fieldrow"><div class="field"><label for="project-name">${tr('projectName')}</label><input id="project-name" placeholder="${tr('projectNameExample')}"></div><div class="field"><label for="project-link">${tr('projectLink')}</label><input id="project-link" type="url" placeholder="https://..."></div></div><div class="field"><label for="project-desc">${tr('projectDesc')}</label><textarea id="project-desc" placeholder="${tr('projectDescExample')}"></textarea></div><button class="btn" data-action="add-project">+ ${tr('addProject')}</button></section>${foot()}`}
function videoScript(){const p=S.profile;const lines=[fmt('scriptHello',{name:p.name||'…'})];if(p.role)lines.push(fmt('scriptJob',{role:p.role}));if(p.summary)lines.push(fmt('scriptAbout',{summary:p.summary}));if(skills().length)lines.push(fmt('scriptSkills',{skills:skills().join(', ')}));if(p.experience)lines.push(fmt('scriptProject',{experience:p.experience}));if(p.achievements)lines.push(fmt('scriptAch',{achievements:p.achievements}));lines.push(fmt('scriptEnd',{goal:p.goal||'…'}));return lines.join('\n\n')}
function video(){return pageHeader('video')+`<div class="grid" style="align-items:start"><div class="card"><h2>${tr('script')}</h2><p class="subtle" style="margin:8px 0 15px">${tr('template')}</p><div class="script" id="video-script">${esc(videoScript())}</div><div class="btn-row" style="margin-top:16px"><button class="btn" data-action="copy-script">${tr('copy')}</button><button class="btn outline" data-page="resume">${tr('edit')} ↗</button></div></div><div class="card"><h2>${tr('videoStructure')}</h2><div class="steps" style="margin-top:15px">${[1,2,3,4].map(n=>`<div class="step"><span class="step-num">${n}</span><div><h3>${tr('v'+n)}</h3><p>${tr('v'+n+'s')}</p></div></div>`).join('')}</div><div class="notice warning" style="margin-top:20px">${tr('videoTip')}</div></div></div>${foot()}`}
const cityList=[['160','Алматы'],['159','Астана'],['205','Шымкент'],['177','Қарағанды'],['40','Қазақстан']];
const knownSkills=['Python','SQL','Excel','Power BI','Tableau','Git','JavaScript','TypeScript','React','Figma','PostgreSQL','Django','FastAPI','Docker','Java','PHP','1C','Photoshop'];
const countSkills=jobs=>knownSkills.map(skill=>({name:skill,count:jobs.filter(job=>new RegExp('(^|[^a-z0-9])'+skill.replace(/[-/\\^$*+?.()|[\]{}]/g,'\\$&')+'(?=$|[^a-z0-9])','i').test(`${job.title} ${job.requirements}`)).length})).filter(v=>v.count>0).sort((a,b)=>b.count-a.count).slice(0,9);
function salary(s){if(!s)return tr('salaryUndisclosed');const from=typeof s.from==='number'?new Intl.NumberFormat(S.lang==='en'?'en-US':'ru-RU').format(s.from):null;const to=typeof s.to==='number'?new Intl.NumberFormat(S.lang==='en'?'en-US':'ru-RU').format(s.to):null;return `${from&&to?from+'–'+to:from?from+'+':to?'≤ '+to:tr('salaryUndisclosed')} ${esc(s.currency||'')}`}
function agentView(){
  const a=S.agent;
  if(agentBusy)return `<section class="card analysis-card" style="margin:15px 0"><h2><span class="spinner"></span> ${tr('agentLoading')}</h2></section>`;
  if(!a)return '';
  const v=a.analysis||{}, skillsList=v.skills||[];
  const evidence=skillsList.slice(0,6).map(skill=>`<div class="skill-evidence"><strong>${esc(skill.name)}</strong> <span class="hint">${skill.count}/${v.sampleSize||0}</span><div class="hint">${(skill.evidence||[]).filter(e=>e.link).slice(0,2).map(e=>`<a href="${esc(e.link)}" target="_blank" rel="noopener noreferrer">${esc(e.title)} ↗</a>`).join(' · ')}</div></div>`).join('');
  const mode=a.mode==='ai'?tr('agentModeAI'):tr('agentModeRules');
  return `<section class="card analysis-card" style="margin:15px 0"><div class="section-row" style="margin:0 0 13px"><h2>${tr('agentTitle')}</h2><span class="state">${mode}</span></div><p class="subtle">${tr('agentSub')}</p><div class="notice warning" style="margin-top:12px">${tr('agentSample')}. ${tr('sampleNote')}</div><div class="grid" style="margin-top:17px"><div><h3>${tr('agentMatched')}</h3><div>${(v.matched||[]).length?(v.matched||[]).map(x=>pitem(x.name)).join(''):'—'}</div></div><div><h3>${tr('agentMissing')}</h3><div>${(v.missing||[]).length?(v.missing||[]).slice(0,9).map(x=>pitem(x.name)).join(''):'—'}</div><p class="hint" style="margin-top:8px">${tr('agentUnknown')}</p></div></div>${a.summary?`<div class="agent-summary">${nl(a.summary)}</div>`:`<p class="notice" style="margin-top:16px">${tr('agentAIUnavailable')}</p>`}<h3 style="margin-top:18px">${tr('agentEvidence')}</h3>${evidence||`<p class="subtle">${tr('agentNoEvidence')}</p>`}</section>`;
}
function marketResults(){
  const d=S.market;if(!d)return `<div class="empty" style="margin-top:17px"><div class="empty-icon">▥</div><h3>${tr('jobEmpty')}</h3></div>`;
  const hits=countSkills(d.vacancies||[]),max=hits.length?hits[0].count:1;
  return `<div class="notice" style="margin:17px 0">${tr('source')}: <strong>HeadHunter (hh.kz)</strong> · ${tr('searchDate')}: ${esc(new Date(d.fetchedAt).toLocaleString(S.lang==='en'?'en-GB':S.lang==='kk'?'kk-KZ':'ru-RU'))}<br>${tr('sampleNote')}</div><div class="grid"><div class="card"><div class="hint">${tr('resultCount')}</div><div style="font-size:31px;font-weight:850">${typeof d.found==='number'?d.found:'—'}</div><div class="hint">${tr('sampleSize')}: ${d.sampleSize}</div><button class="btn soft" data-action="agent" style="margin-top:15px" ${agentBusy?'disabled':''}>${agentBusy?tr('agentLoading'):tr('agentButton')} ↗</button></div><div class="card"><h2>${tr('skillsChart')}</h2>${hits.length?hits.map(x=>`<div class="barline"><label title="${esc(x.name)}">${esc(x.name)}</label><div class="track"><div class="fill" style="width:${Math.round(x.count/max*100)}%"></div></div><b>${x.count}</b></div>`).join(''):`<p class="subtle" style="margin-top:10px">${tr('skillNone')}</p>`}</div></div>${agentView()}<div class="section-row"><h2>${tr('jobList')}</h2><span class="state">${d.sampleSize}</span></div><div class="grid">${(d.vacancies||[]).map(v=>`<div class="job"><h3>${esc(v.title)}</h3><div class="hint">${esc(v.employer||'')}</div><p>${esc(v.requirements||'').slice(0,250)}</p><div class="salary">${salary(v.salary)}</div>${v.link?`<a class="btn outline small" href="${esc(v.link)}" target="_blank" rel="noopener noreferrer" style="margin-top:12px">${tr('openVacancy')} ↗</a>`:''}</div>`).join('')}</div>`;
}
function market(){return pageHeader('market')+`<div class="notice" style="margin-bottom:16px">${tr('sampleNote')}</div><div class="card"><div class="fieldrow"><div class="field"><label for="job-query">${tr('jobQuery')}</label><input id="job-query" placeholder="${tr('jobQueryPlaceholder')}" value="${esc(S.marketParams.query)}"></div><div class="field"><label for="job-city">${tr('location')}</label><select id="job-city">${cityList.map(([id,name])=>`<option value="${id}" ${id===S.marketParams.area?'selected':''}>${name}</option>`).join('')}</select></div></div><button class="btn" data-action="jobs" ${marketBusy?'disabled':''}>${marketBusy?'<span class="spinner"></span> '+tr('loading'):tr('searchJobs')+' ↗'}</button></div><div id="market-results">${marketResults()}</div>${foot()}`}
function audit(){let v=[],p=S.profile;if(!p.name.trim())v.push('auditName');if(!p.role.trim())v.push('auditRole');if(p.summary.trim().length<80)v.push('auditSummary');if(skills().length<3)v.push('auditSkills');if(!p.education.trim())v.push('auditEdu');if(!p.experience.trim())v.push('auditExp');if(!p.achievements.trim())v.push('auditAchievements');if(!/^\S+@\S+\.\S+$/.test(p.email.trim()))v.push('auditEmail');return v.length?v:['auditGood']}
function auditView(){return `<div class="kpi"><div class="ico">◉</div><div><strong>${completed()}%</strong><div class="hint">${tr('auditScore')}</div></div></div><div class="meter"><span style="width:${completed()}%"></span></div><p class="notice warning" style="margin:15px 0">${tr('auditNote')}</p><button class="btn soft" data-action="audit">${tr('auditButton')}</button><div id="audit-output" style="margin-top:15px"></div>`}
function chatMessages(){return `<div class="bubble bot">${tr('chatHello')}</div>${S.messages.map(x=>`<div class="bubble ${x.role==='user'?'user':'bot'}">${esc(x.content)}</div>`).join('')}${chatBusy?'<div class="bubble bot"><span class="spinner"></span></div>':''}`}
function assistant(){return pageHeader('assistant')+`<div class="grid" style="align-items:start"><div class="chat-shell"><div class="chat-title"><div style="font-size:26px">✦</div><div><h3>${tr('chatTitle')}</h3><p>${apiReady?tr('chatReady'):tr('chatOffline')}</p></div></div><div class="chat-body" id="chat-body">${chatMessages()}</div><form id="chat-form" class="chat-controls"><textarea id="chat-input" placeholder="${tr('chatInput')}" aria-label="${tr('chatInput')}" maxlength="4000" ${!apiReady?'disabled':''}></textarea><button type="submit" class="btn" ${!apiReady||chatBusy?'disabled':''}>${tr('send')} ↗</button></form><div class="hint" style="padding:0 15px 13px">${apiReady?tr('privacy'):tr('chatNotReady')}</div></div><div class="card"><h2>${tr('auditTitle')}</h2><div style="margin-top:15px">${auditView()}</div><hr class="divider"><div class="btn-row"><button class="btn outline small" data-page="resume">${tr('edit')} CV ↗</button><button class="btn warn small" data-action="clear-chat">${tr('clearChat')}</button></div></div></div>${foot()}`}
const sections={overview,brand,resume,portfolio,video,market,assistant};
function renderPage(){const content=document.getElementById('content');if(content){content.innerHTML=sections[S.page]();if(S.page==='assistant'){const chat=document.getElementById('chat-body');if(chat)chat.scrollTop=chat.scrollHeight;}}}
function notify(text){let prev=document.querySelector('.toast');if(prev)prev.remove();const x=document.createElement('div');x.className='toast';x.role='status';x.textContent=text;document.body.append(x);setTimeout(()=>x.remove(),3200)}
async function copy(text){try{await navigator.clipboard.writeText(text);notify(tr('copied'))}catch{notify(tr('error'))}}
async function health(){try{const r=await fetch('/api/health');const d=await r.json();apiReady=Boolean(d.aiConfigured)}catch{apiReady=false}if(S.page==='assistant')renderPage()}
async function getJobs(){const input=document.getElementById('job-query'),sel=document.getElementById('job-city');let q=input?.value.trim()||'';if(q.length<2){notify(tr('required'));return}S.marketParams={query:q.slice(0,75),area:sel.value};marketBusy=true;S.agent=null;renderPage();try{const resp=await fetch(`/api/jobs?query=${encodeURIComponent(q)}&area=${encodeURIComponent(S.marketParams.area)}`);const d=await resp.json();if(!resp.ok||!Array.isArray(d.vacancies))throw Error(d.code||'no-data');S.market=d;save()}catch{S.market=null;notify(tr('jobError'))}finally{marketBusy=false;renderPage()}}
async function getAnalysis(){
  if(!S.market||agentBusy)return;
  agentBusy=true;renderPage();
  try{
    const r=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:S.lang,profile:S.profile,query:S.marketParams.query,area:S.marketParams.area})});
    const d=await r.json();if(!r.ok||!d.analysis)throw Error(d.code||'ANALYSIS_FAILED');
    S.agent=d;
  }catch{S.agent=null;notify(tr('agentError'));}
  finally{agentBusy=false;renderPage();}
}
async function sendChat(){if(!apiReady||chatBusy){notify(tr('chatNotReady'));return}const el=document.getElementById('chat-input');const txt=el?.value.trim();if(!txt)return;S.messages.push({role:'user',content:txt.slice(0,4000)});S.messages=S.messages.slice(-10);chatBusy=true;renderPage();try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lang:S.lang,profile:S.profile,messages:S.messages,market:S.market?.vacancies?.slice(0,5)||[]})});const d=await r.json();if(!r.ok||!d.reply)throw Error(d.code||'NO_REPLY');S.messages.push({role:'assistant',content:String(d.reply).slice(0,10000)});S.messages=S.messages.slice(-10);save()}catch{S.messages.push({role:'assistant',content:tr('chatError')})}finally{chatBusy=false;renderPage()}}
function demoData(){const example={name:'Айдана Әли',role:'Junior Data Analyst',city:'Алматы',email:'demo@example.com',summary:'Мен деректер талдауы бағытында білімімді дамытып жүрген студентпін. Электрондық кестелермен жұмыс істеп, оқу жобаларында деректерді тазалау мен қарапайым визуализация жасауды үйреніп жүрмін.',skills:'Excel, SQL, Python',education:'Бакалавриат, 1-курс (ойдан шығарылған дерек)',experience:'Оқу жобасы: интернет-дүкеннің сатылым кестесіне талдау жасау',achievements:'Оқу жобасында 3 көрсеткішке арналған диаграмма дайындадым (демо мысал)',goal:'Деректер талдауы бойынша алғашқы тәжірибе жинау',strengths:'ұқыптылық, талдауға қызығушылық, жүйелі жұмыс',audience:'аналитика командалары мен жұмыс берушілер',value:'деректерді түсінікті қорытындыға айналдыру'};S.profile=example;S.projects=[{name:'Сатылымдарды талдау (демо)',desc:'Ойдан шығарылған оқу жобасы: кестелерді тазалау, негізгі көрсеткіштерді шығару және диаграммалар жасау.',link:''}];S.demoActive=true;S.market=null;S.agent=null;S.messages=[];save();renderPage();notify(tr('demoLoaded'))}
function reset(){if(!confirm(tr('resetConfirm')))return;const keepLang=S.lang;S=blank();S.lang=keepLang;save();shell();notify(tr('allCleared'))}
root.addEventListener('click',async e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.page){S.page=btn.dataset.page;save();shell();return}const action=btn.dataset.action;if(action==='demo'){demoData();return}if(action==='reset'){reset();return}if(action==='print'){window.print();return}if(action==='copy-script'){await copy(videoScript());return}if(action==='copy-brand'){await copy(brandStatement());return}if(action==='add-project'){const name=document.getElementById('project-name')?.value.trim(),desc=document.getElementById('project-desc')?.value.trim(),link=document.getElementById('project-link')?.value.trim();if(!name||!desc){notify(tr('required'));return}if(link&&!/^https?:\/\//i.test(link)){notify('https://');return}S.projects.push({name:name.slice(0,140),desc:desc.slice(0,1500),link:link.slice(0,500)});save();renderPage();notify(tr('projectAdded'));return}if(action==='remove-project'){S.projects.splice(Number(btn.dataset.id),1);save();renderPage();notify(tr('projectRemoved'));return}if(action==='jobs'){await getJobs();return}if(action==='agent'){await getAnalysis();return}if(action==='audit'){const out=document.getElementById('audit-output');out.innerHTML=audit().map(k=>`<div class="auto-check"><b>✓</b><span>${tr(k)}</span></div>`).join('');return}if(action==='clear-chat'){S.messages=[];save();renderPage();return}});
root.addEventListener('input',e=>{const meta=e.target.dataset.meta;if(meta&&Object.hasOwn(S.courseMeta,meta)){S.courseMeta[meta]=e.target.value.slice(0,140);save();return}const key=e.target.dataset.field;if(!key)return;S.profile[key]=e.target.value.slice(0,2500);save();if(S.page==='resume'){const cv=document.getElementById('cv-paper');if(cv)cv.innerHTML=cvPaper();const bar=document.querySelector('.completion-bar');if(bar)bar.style.width=completed()+'%';const label=document.getElementById('cv-completion');if(label)label.textContent=tr('completion')+': '+completed()+'%'}if(S.page==='brand'){const element=document.getElementById('brand-text');if(element)element.textContent=brandStatement()}});
root.addEventListener('change',e=>{if(e.target.id==='language'){S.lang=e.target.value;document.documentElement.lang=S.lang;save();shell()}if(e.target.id==='job-city'){S.marketParams.area=e.target.value;save()}});
root.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();sendChat()}});
document.documentElement.lang=S.lang;shell();health();
